mapper.select:
SELECT * , ROW_NUMBER() OVER (ORDER BY a.num) AS rownum FROM ( select a.*,FORMAT(a.wdate, 'yyyy.MM.dd') AS formatted_date, ROW_NUMBER() OVER (ORDER BY a.num) AS rownum, (SELECT COUNT(*) FROM KCC_EGIS.egis.TBL_NEWS_TAIL b WHERE b.info_num = a.num) AS tail_count from KCC_EGIS.egis.TBL_NEWS a where 1=1 and a.part = 'notice' and a.flag = 'N'
and (a.subject like CONCAT('%', #{searchKeyword}, '%') or a.content like CONCAT('%', #{searchKeyword}, '%'))
) A ORDER BY num desc

select count(*) from ( select a.*,FORMAT(a.wdate, 'yyyy.MM.dd') AS reg_date from KCC_EGIS.egis.TBL_NEWS a where 1=1 and a.part = 'notice' and a.flag = 'N'
and (a.subject like CONCAT('%', #{searchKeyword}, '%') or a.content like CONCAT('%', #{searchKeyword}, '%'))
) A

select count(*) from (
	select *,FORMAT(wdate , 'yyyy.MM.dd') AS formatted_date,
    FORMAT(wdate, 'HH:mm') AS formatted_time 
    from KCC_EGIS.egis.TBL_NEWS_TAIL
	where info_num = #{info_num}
) A

mapper.insert:
insert into KCC_EGIS.egis.TBL_NEWS_TAIL (
 info_num, id, writer, content, ip, wdate, part 
)values(
	 #{info_num}, #{id}, #{writer}, #{content}, #{ip}, getdate(), #{part}
)
